"""Durable source-backed synthesis for completed portions; not scope completion."""
import hashlib,json,pathlib
H=pathlib.Path(__file__).resolve().parent;R=H.parents[1];P='additional_pfp_infrastructure_remaining';prep=json.loads((H/(P+'_preparation.json')).read_text())['files'];rp=H/(P+'.json');r=json.loads(rp.read_text())
def ev(i,a=None,b=None):
 f=prep[i];return {'path':f['path'],'sha256':f['sha256'],'lines':[a or 1,b or f['lines']]}
def claim(id,text,refs,deps,limits):return {'id':'PFPINFRA-C'+id,'claim':text,'evidence':refs,'dependencies':deps,'limitations':limits}
def finding(id,title,detail,refs,probes,action,severity='medium'):return {'id':'PFPINFRA-F'+id,'severity':severity,'title':title,'finding':detail,'evidence':refs,'probes':probes,'next_action':action,'status':'open','scope':'Only the identified source predicates and their declared callers; no untested production reachability claim.'}
r['claims']=[
claim('001','Normal-form metadata and executable predicates are separate layers. Pydantic declarations and YAML loaders preserve vocabulary but do not supply the mathematical witnesses promised by those declarations.',[ev(173),ev(174),ev(175),ev(200),ev(201)],['Domain-specific checker and bound replay evidence'],['A machine_checked status may pass with only a nonempty evidence_required declaration. No new formal proof or broad runtime replay is claimed.']),
claim('002','The SQL pipeline makes a useful explicit conditional claim: minimal total declared SQL keys generate key-to-heading FDs, and key projections are assessed under those FDs; JSON/CSV meaning and complete MVD/JD declarations remain open.',[ev(195,67,215)],['Imported relational closure/chase/decomposition algorithms','SQL totality fences','Truth of admitted schema dependencies'],['No new execution of imported domain algorithms or external fences in this slice. Finite instance checks do not establish schema dependencies.']),
claim('003','The concrete seed verifier checks witness bodies and canonical candidate agreement, improving on a generic acceptance-label boundary.',[ev(233,1,110)],['Pinned domain witness predicates and canonical serialization'],['Mitigates the generic Stage7 interface concern in the application report for this concrete caller only. Does not prove provider effectiveness or universal detector adequacy.']),
claim('004','Selected runtime transports retain explicit native/replay boundaries: QM verify passes experiment plus certificate; replayed Anthropic transport checks an absolute file/hash/size and zero provider calls; sandbox delegates without a Python fallback.',[ev(191),ev(244),ev(241)],['External native host implementation and observation envelope'],['No native or provider call was made. Successful transport can still contain semantic refusal; native observations remain trusted inputs.']),
claim('005','The BQNF implementation contains useful additive maintenance, finite median recomputation and explicit unsupported branches, but operates on SQLite REAL and caller-supplied CDC rather than a checked general cochain complex.',[ev(177),ev(179),ev(194),ev(371,190,299)],['Before-image correctness','Auxiliary frequency/cache consistency','Declared query boundary'],['Floating arithmetic and finite cache diagnostics are not exact rational homology or a no-recomputation complexity theorem.']),
]
r['findings']=[
finding('001','Recompute and Escalate are mapped to admission','Actual RPNF and SCNF contract maps send Recompute and Escalate respectively to Preserve. Dispatcher defines admitted solely by that canonical route. These outcomes therefore become admitted even in controls with nonquiescent empty history or explicit obstruction.',[ev(197,75,104),ev(429),ev(430)],['PFPINFRA-P002','PFPINFRA-P004'],'Make nonaccepting routes unadmitted and separate operation routing from mathematical acceptance.','high'),
finding('002','Replay and minimization labels are not recomputed','RPNF can accept a supplied target with empty history and no fold. SCNF can accept only a measure name as a unique minimizer without a candidate carrier, costs or comparison. Supplied defaults substitute for declared mathematical obligations.',[ev(198,65,148),ev(429),ev(430)],['PFPINFRA-P001','PFPINFRA-P003'],'Require concrete fold/candidate/carrier definitions and independently check the claimed equality or optimum.','high'),
finding('003','PDNF and provenance admissions omit declared membership and replay checks','PDNF accepts duplicate carrier entries and asserted endpoints outside that carrier. Provenance NF can admit null model version, a bare fact and empty lineage. StateNF has a related incomplete local Accept but its actual route map escalates, so that control is not an admission bypass.',[ev(198,11,62),ev(198,151,232),ev(428),ev(442),ev(445)],['PFPINFRA-P005','PFPINFRA-P006','PFPINFRA-P007'],'Validate carriers and endpoint membership; distinguish trace presence from trace replay; retain the StateNF mitigation.'),
finding('004','Metadata validator accepts machine-checked declarations without evidence','v1 validation discards the schema argument and permits wrong declaration/classification shapes; a TODO evidence requirement suffices to support machine_checked status. This is metadata acceptance, not execution of any proof checker.',[ev(201,60,124),ev(182,175,196)],['PFPINFRA-P008'],'Separate declared verification status from checked receipt status and enforce actual schema shapes/source-bound verifier receipts.'),
finding('005','Legacy migration promotes string false and drops evidence fields','Migration uses Python truthiness for qualifies_as_true_normal_form, so the string false becomes established. Source proof obligations, references and obstruction substrate are not carried unless already placed in extensions.',[ev(186),ev(187,436,507)],['PFPINFRA-P009'],'Require strict Boolean input and preserve every meaningful legacy field or explicitly refuse lossy migration.'),
finding('006','Cache consistency receipt ignores a corrupted median','Idle and final BQNF consistency comparisons omit median. A cache with true base median10 and stored median999999 returns Preserve and verified_consistent=True. Active quantile paths also recompute the true median despite Repair labels.',[ev(179,50,107),ev(179,129,258)],['PFPINFRA-P011'],'Include median in declared consistency scope and report actual recomputation cost; bind terminal success to all checked invariants.'),
finding('007','Nested helper commits defeat caller rollback','Relational normalization and CDC/cache helpers commit internally. A normalized enrollment survives an exception in an outer connection transaction. CDC before images are also trusted rather than compared against the stored row.',[ev(193,12,48),ev(194,158,210),ev(179,261,315),ev(184,37,42)],['PFPINFRA-P013'],'Let the transaction owner commit; validate before images and atomic consistency before persistence.'),
finding('008','SQL certificate tables constrain asserted fields without checking witnesses','Raw golden SQL accepts primal objective1 and dual objective2 with asserted gap0. Merkle, Hodge and other stored witness fields likewise do not cause their mathematics to be replayed. This does not bypass a separate verifier or imported totality fences.',[ev(371,300,434)],['PFPINFRA-P012'],'Treat these rows as unverified evidence until a bound independent checker validates arithmetic, chain links and witness relations.'),
finding('009','Demo authority gates accept self-supplied execution dictionaries','Certificate example accepts executed=True/outcome=verified plus policy accepted=True with no certificate body or scope. Reconciliation accepts target_verifier outcome=verified without execution or authenticated binding and authorizes the empty morphism. Pending branches also mark certified before validating structure.',[ev(199,75,194),ev(192,133,250)],['PFPINFRA-P014','PFPINFRA-P015'],'Use injected verifier/policy execution or authenticated bound receipts; require complete packet and explicit scopes; label demo metadata honestly.','high'),
finding('010','Reconciliation custody and account encoding are incomplete','Loss ledger with erased_attributes alone passes without entries or digest. Digest binds entries but not erased attributes. Account/currency concatenation with colon merges distinct pairs; target duplicates overwrite. Comparing a supplied compensation vector is not a proof of nonmembership in a fixed repair image.',[ev(192,58,116),ev(192,211,293)],['PFPINFRA-P016','PFPINFRA-P017'],'Require a complete bound ledger, use tuple keys and exact numeric domains, reject duplicates and specify the actual repair operator before cohomology claims.','high'),
finding('011','Freshness checks admit Boolean budgets and assume the observer order','Python bool is admitted as lag and SLA. Monotonicity helper checks only Boolean responses for one packet and never checks the claimed chain order. It can report success on a reversed order; it is not a lattice/functor proof.',[ev(189,89,164),ev(189,171,204)],['PFPINFRA-P018','PFPINFRA-P019'],'Validate exact finite nonnegative numeric domains, check the supplied order and label per-packet sampling separately from a quantified monotonicity proof.'),
]
r['validation']=[{'path':P+'_checks.json','sha256':hashlib.sha256((H/(P+'_checks.json')).read_bytes()).hexdigest(),'controls':13,'result':'all reproduced','scope':'Read-vetted AST fragments and raw golden SQL in memory; no production imports/providers/native.'},{'path':P+'_checks02.json','sha256':hashlib.sha256((H/(P+'_checks02.json')).read_bytes()).hexdigest(),'controls':6,'result':'all reproduced','scope':'Read-vetted demo functions only; synthetic in-process dictionaries.'}]
rp.write_text(json.dumps(r,indent=2)+'\n')
md=['# PFP infrastructure audit — in progress','',f"{r['full_source_read_count']}/{r['scope_count']} frozen files have complete substantive body reviews; {len(r['remaining_work'])} remain. Parsing/emission does not grant review credit.",'','The normal-form declarations preserve useful assumptions, but several runtime predicates certify supplied flags rather than the promised replay or minimization. Actual RPNF/SCNF route maps admit nonaccepting outcomes. Scoped demo authority checks accept self-supplied verification dictionaries. Bounded controls also expose median-audit, transaction and composite-key defects.','', 'The SQL schema pipeline correctly confines its mathematics to declared key FDs and leaves semantic MVD/JD completeness open. Native adapters retain useful experiment/certificate and replay boundaries; no new native execution or provider performance evidence is claimed.','',f"Nineteen offline controls reproduced the stated cases. Detailed source hashes, exact ranges, limitations and repair actions are in `{P}.json`; per-file pending scope remains explicit."]
(H/(P+'.md')).write_text('\n'.join(md)+'\n')
print(json.dumps({'claims':len(r['claims']),'findings':len(r['findings']),'status':r['status']}))
